406	
407	  <script>
408	    // ── state ──
409	    let data = null;           // parsed array of objects
410	    let columns = [];          // detected column keys
411	    let original = null;       // deep copy for undo
412	    let sortKey = null;
413	    let sortDir = 1;
414	    let currentFile = '';
415	    let computedFields = {};   // { fieldName: { dependsOn: [], compute: fn } }
416	
417	    // ── computed field definitions ──
418	    // Add more definitions here when needed. The editor auto-detects which ones
419	    // apply based on whether all dependsOn columns exist in the loaded data.
420	    const COMPUTED_DEFS = {
421	      combatPower: {
422	        dependsOn: ['国9战力', '国50战力', '国100战力'],
423	        compute: (row) => (Number(row['国9战力']) || 0) + (Number(row['国50战力']) || 0) + (Number(row['国100战力']) || 0),
424	        hint: '= 国9 + 国50 + 国100'
425	      }
426	    };
427	
428	    // ── helpers ──
429	    function $(id) { return document.getElementById(id); }
430	
431	    function toast(msg) {
432	      const el = Object.assign(document.createElement('div'), { className: 'toast', textContent: msg });
433	      document.body.appendChild(el);
434	      setTimeout(() => el.remove(), 2000);
435	    }
436	
437	    function detectColumns(arr) {
438	      if (!arr || !arr.length) return [];
439	      const keys = new Set();
440	      arr.forEach(obj => Object.keys(obj).forEach(k => keys.add(k)));
441	      return Array.from(keys);
442	    }
443	
444	    function normalizeValue(val) {
445	      if (val === null || val === undefined) return '';
446	      if (typeof val === 'object') return JSON.stringify(val);
447	      return String(val);
448	    }
449	
450	    // Check which computed fields apply to the current data
451	    function resolveComputedFields() {
452	      computedFields = {};
453	      if (!data || !data.length) return;
454	      const cols = new Set(detectColumns(data));
455	      for (const [field, def] of Object.entries(COMPUTED_DEFS)) {
456	        if (cols.has(field) && def.dependsOn.every(d => cols.has(d))) {
457	          computedFields[field] = def;
458	        }
459	      }
460	    }
461	
462	    // ── render ──
463	    function render() {
464	      resolveComputedFields();
465	
466	      if (!data || !data.length) {
467	        $('dataTable').style.display = 'none';
468	        $('empty').style.display = '';
469	        $('stats').style.display = 'none';
470	        $('saveBtn').disabled = true;
471	        $('addBtn').disabled = true;
472	        $('pasteBtn').disabled = true;
473	        $('applyBtn').disabled = true;
474	        $('applyBtn').style.opacity = '0.4';
475	        return;
476	      }
477	
478	      $('empty').style.display = 'none';
479	      $('dataTable').style.display = '';
480	      $('saveBtn').disabled = false;
481	      $('addBtn').disabled = false;
482	      $('pasteBtn').disabled = false;
483	      $('applyBtn').disabled = true;
484	      $('applyBtn').style.opacity = '0.4';
485	      $('stats').style.display = 'flex';
486	
487	      columns = detectColumns(data);
488	
489	      // sort
490	      let sorted = [...data];
491	      if (sortKey && columns.includes(sortKey)) {
492	        sorted.sort((a, b) => {
493	          let va = a[sortKey], vb = b[sortKey];
494	          let na = parseFloat(va), nb = parseFloat(vb);
495	          if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
496	          return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
497	        });
498	      }
499	
500	      // head
501	      let headHtml = '<tr><th class="col-index">#</th>';
502	      columns.forEach(col => {
503	        let cls = '';
504	        if (sortKey === col) cls = sortDir === 1 ? 'sort-asc' : 'sort-desc';
505	        if (computedFields[col]) cls += ' col-computed';
506	        const label = computedFields[col] ? col + ' 🔒' : col;
507	        headHtml += `<th class="${cls}" onclick="sortBy('${esc(col)}')">${label}<span class="sort-arrow">${sortKey === col ? (sortDir === 1 ? '▲' : '▼') : ''}</span></th>`;
508	      });
509	      headHtml += '<th class="col-index" style="cursor:default">✕</th></tr>';
510	      $('tableHead').innerHTML = headHtml;
511	
512	      // body
513	      let bodyHtml = '';
514	      sorted.forEach((row, sortedIdx) => {
515	        const dataIdx = data.indexOf(row);
516	        bodyHtml += `<tr>`;
517	        bodyHtml += `<td class="col-index">${sortedIdx + 1}</td>`;
518	        columns.forEach(col => {
519	          if (computedFields[col]) {
520	            // ── computed cell (read-only) ──
521	            let val = normalizeValue(row[col]);
522	            bodyHtml += `<td class="computed">${val}</td>`;
523	          } else {
524	            // ── editable cell ──
525	            let val = normalizeValue(row[col]);
526	            let isMod = original && dataIdx >= 0 && dataIdx < original.length &&
527	              JSON.stringify(row) !== JSON.stringify(original[dataIdx]);
528	            bodyHtml += `<td class="editable${isMod ? ' modified' : ''}">`
529	              + `<input value="${val.replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}"`
530	              + ` data-col="${esc(col)}" data-sorted-idx="${sortedIdx}" data-original="${esc(val)}"`
531	              + ` oninput="markDirty(this)" onfocus="this.select()">`
532	              + `</td>`;
533	          }
534	        });
535	        bodyHtml += `<td><button class="del-btn" onclick="deleteRow(${sortedIdx})" title="删除此行">✕</button></td>`;
536	        bodyHtml += `</tr>`;
537	      });
538	      $('tableBody').innerHTML = bodyHtml;
539	
540	      // stats
541	      $('statFile').textContent = '📄 ' + (currentFile || '未命名数据');
542	      $('statRows').textContent = `📋 ${data.length} 行 × ${columns.length} 列`;
543	      $('statDirty').textContent = '💡 编辑后点击「✏️ 应用修改」保存到数据模型';
544	
545	      // Undo button: show if original snapshot exists
546	      if (original) {
547	        $('undoBtn').style.display = '';
548	        $('undoBtn').disabled = false;
549	      } else {
550	        $('undoBtn').style.display = 'none';
551	      }
552	
553	      let compKeys = Object.keys(computedFields);
554	      $('statComputed').textContent = compKeys.length ? `🔒 自动计算: ${compKeys.join(', ')}` : '';
555	    }
556	
557	    function esc(s) {
558	      return s.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '&quot;');
559	    }
560	
561	    // ── edit helpers ──
562	    function startEdit(td) {
563	      const input = td.querySelector('input');
564	      if (!input || document.activeElement === input) return;
565	      input.focus();
566	    }
567	
568	    // Mark an input (and its td) as dirty when the user types
569	    function markDirty(input) {
570	      const td = input.closest('td');
571	      if (td) td.classList.add('modified');
572	      updateSaveState();
573	    }
574	
575	    // Check if any input differs from its data-original value
576	    function hasUnsavedChanges() {
577	      const inputs = $('tableBody').querySelectorAll('input');
578	      for (const inp of inputs) {
579	        if (inp.dataset.col && inp.value.trim() !== (inp.dataset.original || '')) return true;
580	      }
581	      return false;
582	    }
583	
584	    // Enable/disable save-related UI based on dirty state
585	    function updateSaveState() {
586	      const dirty = hasUnsavedChanges();
587	      $('applyBtn').disabled = !dirty;
588	      $('applyBtn').style.opacity = dirty ? '1' : '0.4';
589	    }
590	
591	    // Read all inputs from DOM, write to data, recalc, re-render
592	    function applyChanges() {
593	      if (!data) return;
594	      const inputs = $('tableBody').querySelectorAll('input');
595	      let changed = 0;
596	
597	      if (!original) original = JSON.parse(JSON.stringify(data));
598	
599	      const sorted = getSortedData();

600	
601	      inputs.forEach(input => {
602	        const col = input.dataset.col;
603	        const sortedIdx = parseInt(input.dataset.sortedIdx);
604	        const newVal = input.value.trim();
605	        const oldVal = (input.dataset.original || '').trim();
606	
607	        if (!col || newVal === oldVal) return;
608	
609	        // auto-detect number
610	        let val = newVal;
611	        if (val !== '' && !isNaN(val) && !/^0\d/.test(val)) val = Number(val);
612	
613	        // Map sortedIdx → data[]
614	        if (sortedIdx >= 0 && sortedIdx < sorted.length) {
615	          const row = sorted[sortedIdx];
616	          const dataIdx = data.indexOf(row);
617	          if (dataIdx >= 0) {
618	            data[dataIdx][col] = val;
619	            recalcRow(data[dataIdx]);
620	            changed++;
621	          }
622	        }
623	      });
624	
625	      if (changed > 0) {
626	        recalcAll(); // ensure cross-row computed consistency
627	        render();
628	        toast(`已应用 ${changed} 个修改`);
629	      } else {
630	        toast('没有需要保存的修改');
631	      }
632	    }
633	
634	    // Recalculate all computed fields for a single row
635	    function recalcRow(row) {
636	      for (const [field, def] of Object.entries(computedFields)) {
637	        row[field] = def.compute(row);
638	      }
639	    }
640	
641	    // Recalculate all computed fields for all rows (e.g. after initial load)
642	    function recalcAll() {
643	      if (!data) return;
644	      resolveComputedFields();
645	      data.forEach(row => recalcRow(row));
646	    }
647	
648	    // ── sort ──
649	    function getSortedData() {
650	      if (!data) return [];
651	      let sorted = [...data];
652	      if (sortKey && columns.includes(sortKey)) {
653	        sorted.sort((a, b) => {
654	          let va = a[sortKey], vb = b[sortKey];
655	          let na = parseFloat(va), nb = parseFloat(vb);
656	          if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
657	          return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
658	        });
659	      }
660	      return sorted;
661	    }
662	
663	    function sortBy(col) {
664	      if (hasUnsavedChanges()) {
665	        if (!confirm('有未保存的修改，排序会导致编辑内容丢失。确定继续排序？')) return;
666	      }
667	      if (sortKey === col) {
668	        sortDir *= -1;
669	      } else {
670	        sortKey = col;
671	        sortDir = 1;
672	      }
673	      render();
674	    }
675	
676	    // ── row operations ──
677	    function addRow() {
678	      if (!data) return;
679	      if (hasUnsavedChanges()) {
680	        if (!confirm('有未保存的修改，添加行会导致编辑内容丢失。确定继续？')) return;
681	      }
682	      if (!original) original = JSON.parse(JSON.stringify(data));
683	      const newRow = {};
684	      columns.forEach(col => {
685	        // computed fields start empty — will be recalc'd
686	        newRow[col] = computedFields[col] ? 0 : '';
687	      });
688	      data.push(newRow);
689	      recalcRow(newRow);
690	      render();
691	      $('tableWrap').scrollTop = $('tableWrap').scrollHeight;
692	      toast('已添加新行');
693	    }
694	
695	    function deleteRow(sortedIdx) {
696	      const sorted = getSortedData();
697	      const row = sorted[sortedIdx];
698	      const dataIdx = data.indexOf(row);
699	      if (dataIdx < 0) return;
700	      if (!original) original = JSON.parse(JSON.stringify(data));
701	      const nameCol = columns.find(c => c.toLowerCase().includes('name') || c === 'heroName') || columns[0];
702	      const name = row[nameCol] || `第${dataIdx + 1}行`;
703	      if (!confirm(`确定要删除 "${name}" 吗？`)) return;
704	      data.splice(dataIdx, 1);
705	      render();
706	      toast(`已删除: ${name}`);
707	    }
708	
709	    // ── undo ──
710	    function undoAll() {
711	      if (!original) return;
712	      if (!confirm('确定撤销所有修改，恢复到加载时的原始数据吗？此操作不可撤销。')) return;
713	      data = JSON.parse(JSON.stringify(original));
714	      original = null;
715	      sortKey = null;
716	      sortDir = 1;
717	      recalcAll();
718	      render();
719	      toast('已恢复到原始数据');
720	    }
721	
722	    // ── load JSON ──
723	    function setData(arr, filename) {
724	      if (!Array.isArray(arr)) {
725	        const found = Object.values(arr).find(v => Array.isArray(v));
726	        if (found) arr = found;
727	        else {
728	          alert('JSON 文件格式不正确：需要包含一个数组，或包含数组的对象。');
729	          return;
730	        }
731	      }
732	      data = arr.map(row => {
733	        const clone = {};
734	        Object.keys(row).forEach(k => { clone[k] = row[k]; });
735	        return clone;
736	      });
737	      original = null;
738	      sortKey = null;
739	      sortDir = 1;
740	      currentFile = filename || '';
741	
742	      // Apply computed field formulas to ensure consistency on load
743	      recalcAll();
744	
745	      render();
746	      toast(`已加载: ${filename || '数据'} (${data.length} 行)`);
747	    }
748	
749	    function loadFile(input) {
750	      const file = input.files[0];
751	      if (!file) return;
752	      currentFile = file.name;
753	      const reader = new FileReader();
754	      reader.onload = () => {
755	        try {
756	          const parsed = JSON.parse(reader.result);
757	          setData(parsed, file.name);
758	        } catch (e) {
759	          alert('JSON 解析失败: ' + e.message);
760	        }
761	      };
762	      reader.readAsText(file);
763	      input.value = '';
764	    }
765	
766	    function loadPreset(path) {
767	      if (!path) return;
768	      $('presetSelect').value = '';
769	      fetch(path)
770	        .then(r => { if (!r.ok) throw new Error(r.status + ' ' + r.statusText); return r.json(); })
771	        .then(json => {
772	          currentFile = path.split('/').pop();
773	          setData(json, currentFile);
774	        })
775	        .catch(err => alert('加载失败: ' + err.message));
776	    }
777	
778	    // ── save ──
779	    function saveJSON() {
780	      if (!data) return;
781	
782	      // Final recalculation before saving to ensure all computed values are correct
783	      recalcAll();
784	
785	      const json = JSON.stringify(data, null, 2);
786	      const blob = new Blob([json], { type: 'application/json' });
787	      const url = URL.createObjectURL(blob);
788	      const a = Object.assign(document.createElement('a'), {
789	        href: url,
790	        download: currentFile || 'data.json'
791	      });
792	      a.click();
793	      URL.revokeObjectURL(url);
794	      toast('JSON 已下载（含自动计算值）');
795	    }
796	
797	    // ── keyboard shortcuts ──
798	    document.addEventListener('keydown', e => {
799	      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
800	        e.preventDefault();
801	        applyChanges();  // first apply any pending edits
802	        saveJSON();      // then download
803	      }
804	      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
805	        e.preventDefault();
806	        applyChanges();
807	      }
808	      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
809	        e.preventDefault();
810	        undoAll();
811	      }
812	    });
813	
814	    // ── drag & drop ──
815	    document.body.addEventListener('dragover', e => { e.preventDefault(); });
816	    document.body.addEventListener('drop', e => {
817	      e.preventDefault();
818	      const file = e.dataTransfer.files[0];
819	      if (file && file.name.endsWith('.json')) {
820	        currentFile = file.name;
821	        const reader = new FileReader();
822	        reader.onload = () => {
823	          try { setData(JSON.parse(reader.result), file.name); }
824	          catch (err) { alert('JSON 解析失败: ' + err.message); }
825	        };
826	        reader.readAsText(file);
