703	function sortTable(th, colIdx) {
704	  const table = th.closest("table");
705	  const tbody = table.querySelector("tbody");
706	  const rows = Array.from(tbody.querySelectorAll("tr"));
707	  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
708	
709	  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
710	  th.classList.add("sorted");
711	  if (isDesc) th.classList.add("desc");
712	
713	  // Determine which heroes list is active
714	  let heroes;
715	  if (gameData.hasLanes) {
716	    if (currentView === "global") {
717	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
718	    } else {
719	      heroes = gameData.lanes[currentLane] || [];
720	    }
721	  } else {
722	    heroes = gameData.heroes;
723	  }
724	
725	  // Build column definitions
726	  let cols;
727	  if (gameData.hasLanes && currentView === "global") {
728	    cols = gameConfig.globalColumns;
729	  } else {
730	    cols = gameConfig.columns;
731	  }
732	
733	  // Handle lane-specific rank column
734	  const col = (colIdx < cols.length) ? cols[colIdx] : { field: "globalRank", type: "rank" };
735	
736	  // 动态找到英雄名列的索引（而非硬编码 cells[1]）
737	  const nameColIdx = cols.findIndex(c => c.field === "name");
738	  rows.sort((a, b) => {
739	    const heroA = heroes.find(h => h.name === a.cells[nameColIdx]?.textContent?.trim());
740	    const heroB = heroes.find(h => h.name === b.cells[nameColIdx]?.textContent?.trim());
741	    const va = heroA ? (col.field === "laneRank" ? heroA.laneRank : heroA[col.field]) : 0;
742	    const vb = heroB ? (col.field === "laneRank" ? heroB.laneRank : heroB[col.field]) : 0;
743	
744	    if (col.type === "tier") {
745	      const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
746	      const ia = order.indexOf(va), ib = order.indexOf(vb);
747	      return isDesc ? ib - ia : ia - ib;
748	    }
749	    const na = parseFloat(va), nb = parseFloat(vb);
750	    if (!isNaN(na) && !isNaN(nb)) {
751	      return isDesc ? nb - na : na - nb;
752	    }
753	    const sa = String(va != null ? va : ""), sb = String(vb != null ? vb : "");
754	    return isDesc ? sb.localeCompare(sa) : sa.localeCompare(sb);
755	  });
756	
757	  rows.forEach(r => tbody.appendChild(r));
758	}
